mapper.select:
SELECT *
FROM NC.user_verification_code
WHERE phone = #{phone}
  AND purpose = #{purpose}
ORDER BY id DESC
LIMIT 1

SELECT *
FROM NC.user_verification_code
WHERE phone = #{phone}
  AND code = #{code}
  AND purpose = #{purpose}
  AND used = 0
  AND expired_at > NOW()
ORDER BY id DESC
LIMIT 1

SELECT *
FROM NC.user_verification_code
WHERE phone = #{phone}
ORDER BY id DESC
LIMIT #{limit}
